import { randomUUID } from "crypto";
import {
  eventBus,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from "../event-bus";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
  // Internal: create a notification
  createNotification(userId: string, message: string): Notification;
  // Internal: wire up event subscriptions
  wireEvents(): void;
}

class NotificationService implements INotificationService {
  private store: Map<string, Notification> = new Map();

  createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.store.get(notificationId);
    if (!notification) {
      throw new Error(`Notification not found: ${notificationId}`);
    }
    const updated: Notification = { ...notification, read: true };
    this.store.set(notificationId, updated);
    return updated;
  }

  wireEvents(): void {
    // "task.assigned" → notify assignee
    eventBus.subscribe("task.assigned", (payload) => {
      const { assigneeId, taskTitle } = payload as TaskAssignedPayload;
      this.createNotification(
        assigneeId,
        `Task '${taskTitle}' assigned to you`
      );
    });

    // "task.statusChanged" → notify assignee (if any)
    eventBus.subscribe("task.statusChanged", (payload) => {
      const { assigneeId, taskTitle, newStatus } = payload as TaskStatusChangedPayload;
      if (assigneeId) {
        this.createNotification(
          assigneeId,
          `Task '${taskTitle}' status changed to ${newStatus}`
        );
      }
    });

    // "comment.added" → notify task assignee (we rely on router to pass assigneeId via taskId lookup)
    // The CommentAddedPayload includes taskId; the router resolves the assignee before creating the comment.
    // Here we subscribe and the payload is enriched by the router (authorId != assigneeId guard is in router).
    eventBus.subscribe("comment.added", (payload) => {
      const { taskTitle, authorId, authorName } = payload as CommentAddedPayload;
      // The assigneeId is embedded in the extended payload delivered by the router
      const extended = payload as CommentAddedPayload & { assigneeId?: string };
      if (extended.assigneeId && extended.assigneeId !== authorId) {
        this.createNotification(
          extended.assigneeId,
          `New comment on task '${taskTitle}' by ${authorName}`
        );
      }
    });
  }
}

export const notificationService = new NotificationService();

